			text = [=[The Obsidian Sentinel is one of the stone guardians of {link:uldaman}Uldaman{/link}, but it is made of dark glass rather than stone. Spells aimed at it are often turned back upon those who cast them. When struck, it splinters. Each splinter falls away as a shard that fights on its own, and the sentinel grows weaker as it breaks.]=],
		},
		{
			title = "Significance",
			text = [=[The sentinel's heart is a source of power so strong that mages covet it. {link:tabetha}Tabetha{/link}, a mage who lives alone in {link:dustwallow-marsh}Dustwallow Marsh{/link}, has sent those she trusts to take it. Her colleagues called her mad for asking.]=],
		},
		{ title = "Deeds", text = "• It guards a cavern of {link:uldaman}Uldaman{/link}." },
	},
	chapters = {
		{
			key = "power-in-uldaman",
			title = "Power in Uldaman",
			hint = "Answer the mage of Dustwallow who needs a power source.",
			unlock = {
				{ type = "quest", id = 1956 },
			},
			text = [=[{link:tabetha}Tabetha{/link} needed a power source, and the best ones, she said, were the oldest and the hardest to get. She named the Obsidian Sentinel. When its source was brought to her, she was delighted, and more delighted still that her doubting colleagues had been proven wrong.]=],
		},
	},
	bonds = {
		{ id = "tabetha", name = "Tabetha", note = "sought its heart" },
	},
})

