			unlock = {
				{ type = "quest", id = 2200 },
				{ type = "quest", id = 2338 },
			},
			text = [=[The journal was the paladin's last work. He had found where each gem had gone. The Shadowforge dwarves had hidden the ruby in their barricades as they fought the troggs for the vault. The troggs had put the topaz in an urn near a camp of {link:ironforge}Ironforge{/link} dwarves. The {link:troggs}trogg{/link} chieftain had taken the sapphire. On the {link:horde}Horde{/link}'s side, the journal could not be read until the troll {link:jarkal-mossmeld}Jarkal Mossmeld{/link} of {link:kargath}Kargath{/link} translated it, in return for a chance to study the necklace himself.]=],
